1	import { lazy, Suspense } from "react";
2	import { Toaster as Sonner } from "@/components/ui/sonner";
3	import { TooltipProvider } from "@/components/ui/tooltip";
4	import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
5	import { BrowserRouter, Routes, Route } from "react-router-dom";
6	import { AuthProvider, useAuth } from "@/hooks/useAuth";
7	import { useFeatureFlag } from "@/hooks/useFeatureFlags";
8	import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
9	import { ThemeProvider } from "@/components/ThemeProvider";
10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	
14	// Lazy-loaded route components for code splitting
15	const Index = lazy(() => import("./pages/Index"));
16	const Auth = lazy(() => import("./pages/Auth"));
17	const Admin = lazy(() => import("./pages/Admin"));
18	const Settings = lazy(() => import("./pages/Settings"));
19	const Profile = lazy(() => import("./pages/Profile"));
20	const Billing = lazy(() => import("./pages/Billing"));
21	const NotFound = lazy(() => import("./pages/NotFound"));
22	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
23	const BookDemo = lazy(() => import("./pages/BookDemo"));
24	const RequestFeature = lazy(() => import("./pages/RequestFeature"));
25	const Changelog = lazy(() => import("./pages/Changelog"));
26	const LandingPage = lazy(() => import("@/components/LandingPage"));
27	
28	const queryClient = new QueryClient();
29	
30	const PageLoader = () => null;
31	
32	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
33	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
34	  const { isAdmin, loading } = useAuth();
35	
36	  // Don't block rendering while loading — only gate when we know maintenance is on
37	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
38	  return <>{children}</>;
39	};
40	
41	const RootRoute = () => {
42	  const { user, loading } = useAuth();
43	  if (loading) return <PageLoader />;
44	  return user ? <Index /> : <LandingPage />;
45	};
46	
47	const App = () => (
48	  <QueryClientProvider client={queryClient}>
49	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
50	      <AuthProvider>
51	        <TooltipProvider>
52	          <Sonner />
53	          <BrowserRouter>
54	            <SeoHead />
55	            <MaintenanceGate>
56	              <Suspense fallback={<PageLoader />}>
57	                <Routes>
58	                  <Route path="/auth" element={<Auth />} />
59	                  <Route path="/" element={<RootRoute />} />
60	                  <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
61	                  <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
62	                  <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
63	                  <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
64	                  <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
65	                  <Route path="/book-demo" element={<BookDemo />} />
66	                  <Route path="/request-feature" element={<RequestFeature />} />
67	                  <Route path="/changelog" element={<Changelog />} />
68	                  <Route path="/payment/callback" element={<PaymentCallback />} />
69	                  <Route path="*" element={<NotFound />} />
70	                </Routes>
71	              </Suspense>
72	            </MaintenanceGate>
73	            <ChatWidget />
74	          </BrowserRouter>
75	        </TooltipProvider>
76	      </AuthProvider>
77	    </ThemeProvider>
78	  </QueryClientProvider>
79	);
80	
81	export default App;
82

1	import { useNavigate } from "react-router-dom";
2	import { useAuth } from "@/hooks/useAuth";
3	import AppHeader from "@/components/AppHeader";
4	import JobSidebar from "@/components/JobSidebar";
5	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
6	
7	/**
8	 * Shared layout with persistent JobSidebar + AppHeader.
9	 * Used by all authenticated pages (Settings, Billing, Admin, etc.).
10	 */
11	const SidebarLayout = ({ children }: { children: React.ReactNode }) => {
12	  const { user } = useAuth();
13	  const navigate = useNavigate();
14	
15	  return (
16	    <SidebarProvider className="h-svh overflow-hidden">
17	      <JobSidebar
18	        selectedJobId={null}
19	        showDashboard={false}
20	        showMyJobs={false}
21	        onNewJob={() => navigate("/?new=1")}
22	        onDashboard={() => navigate("/")}
23	        onMyJobs={() => navigate("/jobs")}
24	        onAuthRequired={() => navigate("/auth")}
25	        isAuthenticated={!!user}
26	      />
27	      <SidebarInset className="h-svh overflow-y-auto">
28	        <AppHeader />
29	        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
30	          <SidebarTrigger />
31	        </div>
32	        {children}
33	      </SidebarInset>
34	    </SidebarProvider>
35	  );
36	};
37	
38	export default SidebarLayout;
