1	import React, { useState, useCallback, useEffect } from "react";
2	import { useSearchParams, useLocation } from "react-router-dom";
3	import { useAuth } from "@/hooks/useAuth";
4	import { supabase } from "@/integrations/supabase/client";
5	import AppHeader from "@/components/AppHeader";
6	import AuthDialog from "@/components/AuthDialog";
7	import JobSidebar from "@/components/JobSidebar";
8	import JobDetailView from "@/components/JobDetailView";
9	import JobsOverviewCard from "@/components/JobsOverviewCard";
10	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
11	import { Card, CardContent } from "@/components/ui/card";
12	import { Badge } from "@/components/ui/badge";
13	import { Button } from "@/components/ui/button";
14	import { Plus, Briefcase, FileText, Coins, CheckCircle2, ChevronRight } from "lucide-react";
15	import { format } from "date-fns";
16	import { toast } from "sonner";
17	
18	export interface PastJob {
19	  id: string;
20	  title: string | null;
21	  job_description: string;
22	  status: string;
23	  created_at: string;
24	  resume_count: number;
25	  jd_analysis_json: any;
26	  dynamic_weights_json: Record<string, number> | null;
27	  inbox_email: string | null;
28	}
29	
30	export interface Result {
31	  id: string;
32	  resume_id: string;
33	  overall_score: number;
34	  missing_skills: string[];
35	  summary: string | null;
36	  interview_questions: any;
37	  filename: string;
38	  file_path: string | null;
39	  candidate_name: string | null;
40	  candidate_email?: string | null;
41	  candidate_phone?: string | null;
42	  candidate_location?: string | null;
43	  // Dynamic scoring fields
44	  hard_fit?: boolean;
45	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
46	  confidence?: number;
47	  strengths_json?: string[];
48	  gaps_json?: string[];
49	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
50	  matched_must_haves?: string[];
51	  missing_must_haves?: string[];
52	  scoring_version?: string;
53	  pending?: boolean;
54	  parsed_json?: any;
55	}
56	
57	export interface ExistingResume {
58	  id: string;
59	  filename: string;
60	  file_path: string | null;
61	  candidate_name: string | null;
62	  created_at: string;
63	}
64	
65	type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";
66	
67	const Index = () => {
68	  const { user, profile } = useAuth();
69	  const [searchParams, setSearchParams] = useSearchParams();
70	  const location = useLocation();
71	
72	  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
73	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
74	  const [view, setView] = useState<ViewMode>(location.pathname === "/jobs" ? "my-jobs" : "dashboard");
75	  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
76	  const [results, setResults] = useState<Result[]>([]);
77	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
78	  const [authOpen, setAuthOpen] = useState(false);
79	
80	  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
81	
82	  const fetchPastJobs = useCallback(async () => {
83	    if (!user) return;
84	    setLoadingPastJobs(true);
85	    try {
86	      const { data: jobs } = await supabase
87	        .from("jobs")
88	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
89	        .eq("user_id", user.id)
90	        .order("created_at", { ascending: false })
91	        .limit(50);
92	      if (jobs) {
93	        setPastJobs(jobs.map((j: any) => ({
94	          id: j.id,
95	          title: j.title,
96	          job_description: j.job_description,
97	          status: j.status,
98	          created_at: j.created_at,
99	          resume_count: j.resumes?.[0]?.count ?? 0,
100	          jd_analysis_json: j.jd_analysis_json,
101	          dynamic_weights_json: j.dynamic_weights_json,
102	          inbox_email: j.inbox_email ?? null,
103	        })));
104	      }
105	    } catch (err) {
106	      toast.error("Failed to load jobs");
107	    } finally {
108	      setLoadingPastJobs(false);
109	    }
110	  }, [user]);
111	
112	  useEffect(() => {
113	    fetchPastJobs();
114	  }, [fetchPastJobs]);
115	
116	  // Sync view with route path
117	  useEffect(() => {
118	    if (location.pathname === "/jobs") {
119	      setView("my-jobs");
120	      setSelectedJobId(null);
121	    }
122	  }, [location.pathname]);
123	
124	  // Handle URL params for deep linking
125	  useEffect(() => {
126	    const jobParam = searchParams.get("job");
127	    const newParam = searchParams.get("new");
128	
129	    if (jobParam && user) {
130	      loadJobData(jobParam);
131	      setSearchParams({}, { replace: true });
132	    } else if (newParam && user) {
133	      handleNewJob();
134	      setSearchParams({}, { replace: true });
135	    }
136	    // eslint-disable-next-line react-hooks/exhaustive-deps
137	  }, [searchParams, user]);
138	
139	  const loadJobData = async (jobId: string) => {
140	    setSelectedJobId(jobId);
141	    setView("job-detail");
142	    try {
143	      const [resumesRes, resumeListRes] = await Promise.all([
144	        supabase
145	          .from("resumes")
146	          .select("id, filename, file_path, candidate_name, created_at")
147	          .eq("job_id", jobId)
148	          .order("created_at", { ascending: false }),
149	        supabase
150	          .from("resumes")
151	          .select("id, filename, file_path, candidate_name, parsed_json")
152	          .eq("job_id", jobId),
153	      ]);
154	
155	      const resumes = resumesRes.data ?? [];
156	      setExistingResumes(resumes);
157	
158	      const resumeData = (resumeListRes.data ?? []) as Array<{
159	        id: string;
160	        filename: string;
161	        file_path: string | null;
162	        candidate_name: string | null;
163	        parsed_json?: any;
164	      }>;
165	      if (resumeData.length === 0) {
166	        setResults([]);
167	        return;
168	      }
169	
170	      const resumeIds = resumeData.map((r) => r.id);
171	      const { data: resultData } = await supabase
172	        .from("results")
173	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
174	        .in("resume_id", resumeIds);
175	
176	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
177	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
178	        const resume = resumeMap.get(r.resume_id);
179	        const parsed = resume?.parsed_json as any;
180	        return {
181	          ...r,
182	          overall_score: r.overall_score ?? 0,
183	          missing_skills: r.missing_skills ?? [],
184	          filename: resume?.filename ?? "Unknown",
185	          file_path: resume?.file_path ?? null,
186	          candidate_name: resume?.candidate_name ?? null,
187	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
188	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
189	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
190	          parsed_json: resume?.parsed_json ?? null,
191	        };
192	      });
193	      // Deduplicate by resume_id — keep highest scoring result per resume
194	      const deduped = new Map<string, Result>();
195	      for (const r of allMerged) {
196	        const existing = deduped.get(r.resume_id);
197	        if (!existing || r.overall_score > existing.overall_score) {
198	          deduped.set(r.resume_id, r);
199	        }
200	      }
201	      const merged = Array.from(deduped.values());
202	      merged.sort((a, b) => b.overall_score - a.overall_score);
203	      setResults(merged);
204	    } catch (err) {
205	      toast.error("Failed to load job data");
206	    }
207	  };
208	
209	  const handleNewJob = () => {
210	    setSelectedJobId(null);
211	    setView("new-job");
212	    setResults([]);
213	    setExistingResumes([]);
214	  };
215	
216	  const handleGoToDashboard = () => {
217	    setSelectedJobId(null);
218	    setView("dashboard");
219	    setResults([]);
220	    setExistingResumes([]);
221	  };
222	
223	  const handleGoToMyJobs = () => {
224	    setSelectedJobId(null);
225	    setView("my-jobs");
226	    setResults([]);
227	    setExistingResumes([]);
228	  };
229	
230	  const handleJobCreated = (job: PastJob) => {
231	    setPastJobs((prev) => [job, ...prev]);
232	    setSelectedJobId(job.id);
233	    loadJobData(job.id);
234	  };
235	
236	  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
237	    setPastJobs((prev) =>
238	      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
239	    );
240	  };
241	
242	  const requireAuth = useCallback(() => {
243	    if (!user) { setAuthOpen(true); return true; }
244	    return false;
245	  }, [user]);
246	
247	  return (
248	    <SidebarProvider className="h-svh overflow-hidden">
249	      <JobSidebar
250	        pastJobs={pastJobs}
251	        selectedJobId={selectedJobId}
252	        showDashboard={view === "dashboard"}
253	        showMyJobs={view === "my-jobs"}
254	        loadingPastJobs={loadingPastJobs}
255	        onSelectJob={loadJobData}
256	        onNewJob={handleNewJob}
257	        onDashboard={handleGoToDashboard}
258	        onMyJobs={handleGoToMyJobs}
259	        onAuthRequired={() => setAuthOpen(true)}
260	        isAuthenticated={!!user}
261	      />
262	
263	      <SidebarInset className="h-svh overflow-y-auto">
264	        <AppHeader />
265	        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
266	          <SidebarTrigger />
267	          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
268	        </div>
269	
270	        {/* Dashboard view */}
271	        {view === "dashboard" && user ? (
272	          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
273	            {/* Hero Section — Greeting + Create Button */}
274	            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
275	              <div>
276	                <h1 className="text-2xl font-bold text-foreground">
277	                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
278	                </h1>
279	                <p className="text-sm text-muted-foreground mt-1">
280	                  Here's an overview of your hiring activity and insights.
281	                </p>
282	              </div>
283	              <Button size="lg" className="gap-2 shadow-md px-6" onClick={handleNewJob}>
284	                <Plus className="h-4 w-4" /> Create Job
285	              </Button>
286	            </div>
287	
288	            {/* Stats Cards */}
289	            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
290	              {[
291	                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
292	                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
293	                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
294	                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
295	              ].map((s) => (
296	                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
297	                  <CardContent className="px-5 py-4 flex items-center gap-4">
298	                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
299	                      <s.icon className="h-5 w-5" />
300	                    </div>
301	                    <div>
302	                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
303	                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
304	                    </div>
305	                  </CardContent>
306	                </Card>
307	              ))}
308	            </div>
309	
310	            {/* Recent Jobs */}
311	            {pastJobs.length > 0 && (
312	              <div className="space-y-3">
313	                <div className="flex items-center justify-between">
314	                  <h2 className="text-sm font-semibold text-foreground">Recent Jobs</h2>
315	                  <button onClick={handleGoToMyJobs} className="text-xs font-medium text-primary hover:text-primary/80 transition-colors">
316	                    View All Jobs →
317	                  </button>
318	                </div>
319	                <div className="grid gap-3">
320	                  {pastJobs.slice(0, 5).map((job) => (
321	                    <Card key={job.id} className="cursor-pointer hover:shadow-md transition-all border border-border/60" onClick={() => loadJobData(job.id)}>
322	                      <CardContent className="px-5 py-3.5 flex items-center justify-between">
323	                        <div className="flex items-center gap-3 min-w-0">
324	                          <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
325	                            <Briefcase className="h-4 w-4 text-primary" />
326	                          </div>
327	                          <div className="min-w-0">
328	                            <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
329	                            <p className="text-xs text-muted-foreground mt-0.5">
330	                              {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
331	                            </p>
332	                          </div>
333	                        </div>
334	                        <div className="flex items-center gap-3 shrink-0">
335	                          <Badge
336	                            variant={job.status === "completed" ? "success" : job.status === "pending" || job.status === "processing" ? "warning" : "outline"}
337	                            className="text-xs"
338	                          >
339	                            {job.status.charAt(0).toUpperCase() + job.status.slice(1)}
340	                          </Badge>
341	                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
342	                        </div>
343	                      </CardContent>
344	                    </Card>
345	                  ))}
346	                </div>
347	              </div>
348	            )}
349	
350	            {/* Getting started guide — show only for new users */}
351	            {pastJobs.length === 0 && !loadingPastJobs && (
352	              <Card>
353	                <CardContent className="px-5 py-4 space-y-3">
354	                  <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
355	                  <div className="space-y-2.5">
356	                    {[
357	                      { step: "1", text: "Click \"Create New Job\" and paste a job description" },
358	                      { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
359	                      { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
360	                    ].map((item) => (
361	                      <div key={item.step} className="flex items-start gap-3 text-sm">
362	                        <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
363	                        <span className="text-muted-foreground">{item.text}</span>
364	                      </div>
365	                    ))}
366	                  </div>
367	                </CardContent>
368	              </Card>
369	            )}
370	          </div>
371	        ) : view === "my-jobs" && user ? (
372	          /* My Jobs view — full management */
373	          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
374	            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
375	              <div>
376	                <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
377	                <p className="text-sm text-muted-foreground mt-1">Manage all your job postings.</p>
378	              </div>
379	              <Button size="lg" className="gap-2 shadow-md px-6" onClick={handleNewJob}>
380	                <Plus className="h-4 w-4" /> Create Job
381	              </Button>
382	            </div>
383	            <JobsOverviewCard jobs={pastJobs} loading={loadingPastJobs} onSelectJob={loadJobData} />
384	          </div>
385	        ) : (
386	          <JobDetailView
387	            selectedJobId={selectedJobId}
388	            selectedJob={selectedJob}
389	            results={results}
390	            setResults={setResults}
391	            existingResumes={existingResumes}
392	            setExistingResumes={setExistingResumes}
393	            onJobCreated={handleJobCreated}
394	            onAuthRequired={() => setAuthOpen(true)}
395	            isAuthenticated={!!user}
396	            pastJobs={pastJobs}
397	            onJobUpdated={handleJobUpdated}
398	          />
399	        )}
400	      </SidebarInset>
401	
402	      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
403	    </SidebarProvider>
404	  );
405	};
406	
407	export default Index;
