22	function getInitials(email?: string | null): string {
23	  if (!email) return "?";
24	  const name = email.split("@")[0];
25	  const parts = name.split(/[._-]/);
26	  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
27	  return name[0]?.toUpperCase() || "?";
28	}
